import { generateText } from "ai";
import type { ModelPool } from "./models.js";

/**
 * Short, human titles for the sidebar ("Cheapest Postgres hosting for a small SaaS", not the whole first message).
 * Generated by a free model only: a title is never worth a paid call. If no free model answers in time, a
 * deterministic rewrite of the question is used, so a title always appears.
 */

const LEAD = /^(hey|hi|hello|please|can you|could you|would you|will you|i want to know|i'd like to know|i need to know|tell me|show me|help me|i need|i want|let me know|do you know|quick question|question)[,:]?\s+/i;
const QUESTION_LEAD = /^(what is|what's|what are|what was|how much is|how much does|how do i|how do you|how can i|who is|who's|where is|when is|is there|are there|which is|why is|why does|does|do|is|are|can|should)\s+(the\s+|a\s+|an\s+)?/i;

export function heuristicTitle(question: string): string {
  let t = question.replace(/\s+/g, " ").trim();
  for (let i = 0; i < 2; i++) t = t.replace(LEAD, "");
  t = t.replace(QUESTION_LEAD, "").replace(/[?!.]+$/g, "").trim();
  if (!t) t = question.trim();
  t = t.charAt(0).toUpperCase() + t.slice(1);
  if (t.length <= 48) return t;
  const cut = t.slice(0, 48);
  return `${cut.slice(0, Math.max(cut.lastIndexOf(" "), 24))}…`;
}

export function cleanTitle(raw: string): string | undefined {
  const t = raw.split("\n")[0]!.replace(/^["'“”‘’`*#\s-]+|["'“”‘’`*.!?:\s]+$/g, "").replace(/^title:\s*/i, "").replace(/\s+/g, " ").trim();
  if (!t || t.length > 70 || t.split(" ").length > 10) return undefined;
  return t.charAt(0).toUpperCase() + t.slice(1);
}

type Generate = (model: Parameters<typeof generateText>[0]["model"], prompt: string, signal: AbortSignal) => Promise<string>;

const defaultGenerate: Generate = async (model, prompt, signal) =>
  (await generateText({ model, prompt, maxOutputTokens: 24, maxRetries: 0, abortSignal: signal })).text;

export async function generateTitle(
  models: ModelPool, question: string, opts: { generate?: Generate; timeoutMs?: number } = {},
): Promise<string> {
  const generate = opts.generate ?? defaultGenerate;
  const free = models.ordered().filter((e) => !e.name.startsWith("anthropic")).slice(0, 2);
  const prompt =
    `Write a title of 3 to 6 words for a chat that starts with this message. Reply with the title only: no quotes, no full stop.\n\nMessage: ${question.slice(0, 400)}`;
  for (const entry of free) {
    try {
      const title = cleanTitle(await generate(entry.model, prompt, AbortSignal.timeout(opts.timeoutMs ?? 6_000)));
      if (title) return title;
    } catch {
      /* try the next free model, then the deterministic title */
    }
  }
  return heuristicTitle(question);
}
